def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, remaining_qty)]
    sell_book = []  # [(price, arrival_time, id, remaining_qty)]
    order_info = {}  # id -> (side, original_qty, arrival_time)
    arrival_counter = 0

    def find_and_remove_order(order_id, side):
        nonlocal buy_book, sell_book
        if side == 'buy':
            for i, (price, arrival, oid, qty) in enumerate(buy_book):
                if oid == order_id:
                    buy_book.pop(i)
                    return True
        else:
            for i, (price, arrival, oid, qty) in enumerate(sell_book):
                if oid == order_id:
                    sell_book.pop(i)
                    return True
        return False

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_info:
                side = order_info[order_id][0]
                find_and_remove_order(order_id, side)
                del order_info[order_id]

        elif order[0] == 'limit':
            order_type, order_id, side, price, qty = order
            remaining = qty

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest)
                i = 0
